-- ROLLBACK 910: remove the two analytics capabilities, their grants, and the pseudonym salt column.
-- Refuses nothing: the grants are position defaults and the salt is regenerated by a re-apply (pseudonyms then change).
delete from hq_position_capability where capability_code in ('hq.scholar.analytics.view', 'hq.scholar.analytics.identifiable.read');
delete from hq_capability where code in ('hq.scholar.analytics.view', 'hq.scholar.analytics.identifiable.read');
alter table hq_config drop column if exists analytics_pseudonym_salt;
notify pgrst, 'reload schema';
